// Pedidos web pendientes -> baja el stock en FacturaScripts por referencia (SKU).
// Marca el pedido como volcado en la web solo si todas sus líneas fueron bien.
const FS_BASE    = 'http://127.0.0.1/api/3';
const FS_TOKEN   = 'PON_TU_TOKEN_FS';
const WEB_ORDERS = 'http://127.0.0.1:3000/api/sync/orders';
const WEB_SECRET = 'PON_TU_SECRETO_SYNC';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const enc = (o) => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');

// 1) Pedidos web pendientes de volcar
const web = await this.helpers.httpRequest({
  method: 'GET', url: WEB_ORDERS,
  headers: { 'X-Sync-Secret': WEB_SECRET }, json: true,
});
const pedidos = web.orders || [];

const out = [];
for (const o of pedidos) {
  let okPedido = true;
  for (const it of (o.items || [])) {
    const ref = it.sku ? String(it.sku).trim() : '';
    const qty = Number(it.qty) || 0;
    if (!ref || qty <= 0) { out.push({ json: { pedido: o.ref, linea: it.name, saltado: 'sin sku' } }); okPedido = false; continue; }
    try {
      // stock actual en FS por referencia
      const st = await this.helpers.httpRequest({
        method: 'GET',
        url: FS_BASE + '/stocks?filter[referencia]=' + encodeURIComponent(ref) + '&limit=1',
        headers: { 'X-Auth-Token': FS_TOKEN }, json: true,
      });
      const filas = Array.isArray(st) ? st : (st.data || []);
      if (!filas.length || !filas[0].idstock) {
        out.push({ json: { pedido: o.ref, referencia: ref, error: 'sin fila de stock en FS (regulariza antes)' } });
        okPedido = false; continue;
      }
      const fila = filas[0];
      const nueva = Math.max(0, (Number(fila.cantidad) || 0) - qty);
      await this.helpers.httpRequest({
        method: 'PUT',
        url: FS_BASE + '/stocks/' + fila.idstock,
        headers: { 'X-Auth-Token': FS_TOKEN, 'Content-Type': 'application/x-www-form-urlencoded' },
        body: enc({ cantidad: nueva }),
      });
      out.push({ json: { pedido: o.ref, referencia: ref, antes: fila.cantidad, vendido: qty, ahora: nueva } });
    } catch (e) {
      out.push({ json: { pedido: o.ref, referencia: ref, error: String((e && e.message) || e) } });
      okPedido = false;
    }
    await sleep(1500); // pausa anti-429
  }
  // marcar el pedido como volcado SOLO si todo fue bien
  if (okPedido) {
    try {
      await this.helpers.httpRequest({
        method: 'POST', url: WEB_ORDERS,
        headers: { 'X-Sync-Secret': WEB_SECRET },
        body: { id: o.id }, json: true,
      });
      out.push({ json: { pedido: o.ref, marcado: true } });
    } catch (e) {
      out.push({ json: { pedido: o.ref, marcado: false, error: String((e && e.message) || e) } });
    }
  }
}
return out.length ? out : [{ json: { info: 'sin pedidos pendientes' } }];
